void Halfedge_Mesh::flip_orientation() {
	//remember the current loop structure and corner data:
	std::unordered_map< HalfedgeRef, HalfedgeRef > next_of;
	std::unordered_map< HalfedgeRef, Vec2 > uv_of;
	std::unordered_map< HalfedgeRef, Vec3 > normal_of;
	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		next_of[h] = h->next;
		uv_of[h] = h->corner_uv;
		normal_of[h] = h->corner_normal;
	}

	//find the predecessor of each halfedge in its loop:
	std::unordered_map< HalfedgeRef, HalfedgeRef > prev_of;
	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		prev_of[h->next] = h;
	}

	//reverse every edge (each halfedge now points from the opposite vertex):
	for (EdgeRef e = edges.begin(); e != edges.end(); ++e) {
		std::swap(e->halfedge->vertex, e->halfedge->twin->vertex);
	}

	//reverse every loop:
	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		h->next = prev_of[h];
	}

	//corner data stays with its (vertex, face) pair; the halfedge that now
	//leaves a given vertex in a given face is the one whose old successor
	//used to leave that vertex:
	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		h->corner_uv = uv_of[next_of[h]];
		h->corner_normal = normal_of[next_of[h]];
	}

	//re-point vertices at halfedges that still leave them:
	for (VertexRef v = vertices.begin(); v != vertices.end(); ++v) {
		v->halfedge = v->halfedge->twin;
	}

	//faces still consist of the same halfedges, so face halfedge pointers remain valid.
}

