	//should the faces on either side of an edge be smoothed together?
	auto smooth_across = [&](EdgeRef e) -> bool {
		if (e->on_boundary()) return false; //smoothing never crosses the boundary
		if (threshold < 0.0f) return true; //negative threshold: everything is smooth
		if (e->sharp) return false; //explicitly sharp edges are always sharp
		if (threshold > 180.0f) return false; //threshold beyond 180: everything is sharp
		float cos_angle = dot(e->halfedge->face->normal(), e->halfedge->twin->face->normal());
		cos_angle = std::max(-1.0f, std::min(1.0f, cos_angle));
		return Degrees(std::acos(cos_angle)) <= threshold;
	};

	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		if (f->boundary) continue;
		HalfedgeRef h = f->halfedge;
		do {
