				ok = ok && std::abs(h.corner_normal.x) < 1e-3f && h.corner_normal.y > 0.5f && h.corner_normal.z > 0.5f;
			}
		}
		check(ok, "set_corner_normals: 90deg ridge smoothed at 60deg threshold");
		mesh.set_corner_normals(30.0f);
		ok = true;
		for (auto const &h : mesh.halfedges) {
			if (h.face->boundary) continue;
			ok = ok && close(h.corner_normal, h.face->normal(), 1e-3f);
		}
		check(ok, "set_corner_normals: 90deg ridge flat at 30deg threshold");
	}
}

static void test_corner_uvs_per_face() {
	Halfedge_Mesh mesh = cube_mesh();
	mesh.set_corner_uvs_per_face();
	bool ok = true;
	for (auto const &f : mesh.faces) {
		if (f.boundary) {
			continue;
		}
		//each corner of a quad face must get a distinct uv:
		std::vector<Vec2> uvs;
		auto h = f.halfedge;
		do {
			uvs.emplace_back(h->corner_uv);
			h = h->next;
		} while (h != f.halfedge);
		for (size_t i = 0; i < uvs.size(); ++i) {
			for (size_t j = i + 1; j < uvs.size(); ++j) {
				ok = ok && (uvs[i] - uvs[j]).norm() > 1e-3f;
			}
		}
		//cube face spans 2 units in each axis of its tangent frame:
		for (auto const &uv : uvs) {
			ok = ok && std::abs(uv.x) <= 1.0f + 1e-3f && std::abs(uv.y) <= 1.0f + 1e-3f;
		}
	}
	check(ok, "set_corner_uvs_per_face: cube faces get distinct, face-local uvs");
}

int main() {
	test_flip_orientation();
	test_corner_normals();
	test_corner_uvs_per_face();
	if (failures) {
		printf("%d check(s) failed.\n", failures);
		return 1;
	}
	printf("all checks passed.\n");
	return 0;
}

